<?php
declare(strict_types=1);
// Finance: product / service lines, optional signatures and the discussion on a document. Runs from /upgrade.php, and by itself the first time Finance is opened.
require_once __DIR__ . '/migrate.php';

/** Finance: product / service lines, optional signatures, vendors, document looks, templates and the discussion on a document. Safe to run again. */
function migrate_fin_ext(): array {
    $log = [];
    if (!col_exists('fin_items', 'kind')) { db()->exec("ALTER TABLE fin_items ADD COLUMN kind VARCHAR(8) NULL"); $log[] = 'Finance items: product / service type added.'; }
    if (!col_exists('doc_approvals', 'require_sig')) { db()->exec('ALTER TABLE doc_approvals ADD COLUMN require_sig TINYINT(1) NOT NULL DEFAULT 1'); $log[] = 'Approvals: optional signature added.'; }
    db()->exec("CREATE TABLE IF NOT EXISTS vendors (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(190) NOT NULL, contact_name VARCHAR(160) NULL, email VARCHAR(190) NULL, phone VARCHAR(60) NULL, address VARCHAR(500) NULL, notes TEXT NULL,
        created_by INT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY (name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    if (!col_exists('products', 'vendor_id')) { db()->exec('ALTER TABLE products ADD COLUMN vendor_id INT UNSIGNED NULL, ADD KEY (vendor_id)'); $log[] = 'Products and services: vendor added.'; }
    db()->exec("CREATE TABLE IF NOT EXISTS fin_styles (scope VARCHAR(40) NOT NULL PRIMARY KEY, data MEDIUMTEXT NOT NULL, updated_by INT UNSIGNED NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS fin_templates (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, doc_type VARCHAR(20) NOT NULL, data MEDIUMTEXT NOT NULL, styles MEDIUMTEXT NULL, created_by INT UNSIGNED NULL,
        created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY (doc_type)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS fin_comments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, doc_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, to_user_id INT UNSIGNED NULL, body TEXT NOT NULL,
        created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY (doc_id,id), KEY (to_user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS fin_letterheads (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, art_path VARCHAR(64) NULL, art_mime VARCHAR(40) NULL, pad_top DECIMAL(5,1) NOT NULL DEFAULT 52, pad_bottom DECIMAL(5,1) NOT NULL DEFAULT 44, pad_left DECIMAL(5,1) NOT NULL DEFAULT 22, pad_right DECIMAL(5,1) NOT NULL DEFAULT 22, is_default TINYINT(1) NOT NULL DEFAULT 0, created_by INT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS fin_letters (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(200) NOT NULL, letterhead_id INT UNSIGNED NULL, body MEDIUMTEXT NOT NULL, created_by INT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY (updated_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS vault_shares (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, item_id INT UNSIGNED NOT NULL, owner_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, note VARCHAR(300) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY (item_id,user_id), KEY (user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    if (!(int)(one('SELECT COUNT(*) n FROM fin_letterheads')['n'] ?? 0)) { q("INSERT INTO fin_letterheads (name,art_path,art_mime,is_default) VALUES ('Aerosub letterhead','builtin','image/png',1)"); $log[] = 'Letters: the Aerosub letterhead was added.'; }
    db()->exec("CREATE TABLE IF NOT EXISTS news_feeds (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, url VARCHAR(500) NOT NULL, keywords TEXT NULL, exclude_words TEXT NULL, department_id INT UNSIGNED NULL, max_items SMALLINT UNSIGNED NOT NULL DEFAULT 12, keep_days SMALLINT UNSIGNED NOT NULL DEFAULT 7, every_min SMALLINT UNSIGNED NOT NULL DEFAULT 60, active TINYINT(1) NOT NULL DEFAULT 1, last_fetch DATETIME NULL, last_error VARCHAR(250) NULL, last_added INT NOT NULL DEFAULT 0, created_by INT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS news_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, feed_id INT UNSIGNED NOT NULL, guid_hash CHAR(40) NOT NULL, title VARCHAR(250) NOT NULL, summary VARCHAR(500) NULL, link VARCHAR(500) NULL, published_at DATETIME NOT NULL, matched VARCHAR(200) NULL, UNIQUE KEY (feed_id,guid_hash), KEY (published_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS task_horns (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, task_id INT UNSIGNED NOT NULL, from_user_id INT UNSIGNED NOT NULL, to_user_id INT UNSIGNED NOT NULL, message VARCHAR(160) NOT NULL, status ENUM('open','snoozed','replied') NOT NULL DEFAULT 'open', snooze_until DATETIME NULL, snoozes TINYINT UNSIGNED NOT NULL DEFAULT 0, reply VARCHAR(20) NULL, replied_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY (to_user_id,status), KEY (task_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    foreach ([['kind', 'VARCHAR(8) NULL'], ['parent_id', 'INT UNSIGNED NULL'], ['start_date', 'DATE NULL'], ['window_scope', 'VARCHAR(5) NULL'], ['transfer_state', 'VARCHAR(8) NULL']] as [$c, $def]) if (!col_exists('tasks', $c)) { db()->exec("ALTER TABLE tasks ADD COLUMN $c $def"); if ($c === 'parent_id') db()->exec('ALTER TABLE tasks ADD KEY (parent_id)'); }
    db()->exec("CREATE TABLE IF NOT EXISTS task_deps (task_id INT UNSIGNED NOT NULL, depends_on_id INT UNSIGNED NOT NULL, PRIMARY KEY (task_id,depends_on_id), KEY (depends_on_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS task_windows (task_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, start_date DATE NOT NULL, due_date DATE NOT NULL, PRIMARY KEY (task_id,user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS task_subs (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, task_id INT UNSIGNED NOT NULL, title VARCHAR(200) NOT NULL, done TINYINT(1) NOT NULL DEFAULT 0, user_id INT UNSIGNED NULL, created_by INT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, done_at DATETIME NULL, KEY (task_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS vault_drives (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, name VARCHAR(160) NOT NULL, folder_id VARCHAR(120) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY (user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS ai_settings (id TINYINT UNSIGNED PRIMARY KEY, enabled TINYINT(1) NOT NULL DEFAULT 0, api_key_enc TEXT NULL, model VARCHAR(60) NOT NULL DEFAULT 'claude-sonnet-5-5', web_search TINYINT(1) NOT NULL DEFAULT 1, daily_limit SMALLINT UNSIGNED NOT NULL DEFAULT 40, instructions TEXT NULL, updated_by INT UNSIGNED NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS ai_chats (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY (user_id,updated_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS ai_messages (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, chat_id INT UNSIGNED NOT NULL, role ENUM('user','assistant') NOT NULL, body MEDIUMTEXT NOT NULL, sources TEXT NULL, proposals TEXT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY (chat_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS ai_usage (user_id INT UNSIGNED NOT NULL, day DATE NOT NULL, msgs INT UNSIGNED NOT NULL DEFAULT 0, in_tokens INT UNSIGNED NOT NULL DEFAULT 0, out_tokens INT UNSIGNED NOT NULL DEFAULT 0, PRIMARY KEY (user_id,day)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    if (!col_exists('ai_settings', 'show_bubble')) db()->exec('ALTER TABLE ai_settings ADD COLUMN show_bubble TINYINT(1) NOT NULL DEFAULT 1');
    db()->exec("CREATE TABLE IF NOT EXISTS chat_rooms (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, kind ENUM('dm','group') NOT NULL, name VARCHAR(80) NULL, dm_key VARCHAR(30) NULL, created_by INT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY (dm_key), KEY (updated_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS chat_members (room_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, role ENUM('owner','member') NOT NULL DEFAULT 'member', last_read_id INT UNSIGNED NOT NULL DEFAULT 0, muted TINYINT(1) NOT NULL DEFAULT 0, joined_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (room_id,user_id), KEY (user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS chat_messages (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, room_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, kind ENUM('text','file','task','system') NOT NULL DEFAULT 'text', body TEXT NULL, file_name VARCHAR(190) NULL, file_mime VARCHAR(100) NULL, file_size INT UNSIGNED NULL, file_path VARCHAR(64) NULL, task_id INT UNSIGNED NULL, task_shared TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, edited_at DATETIME NULL, deleted_at DATETIME NULL, KEY (room_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS fin_memory (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, kind VARCHAR(24) NOT NULL DEFAULT 'line', text VARCHAR(1200) NOT NULL, unit VARCHAR(30) NULL, unit_price DECIMAL(14,3) NULL, category VARCHAR(120) NULL, freq VARCHAR(60) NULL, item_kind VARCHAR(8) NULL, uses INT UNSIGNED NOT NULL DEFAULT 1, last_used DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY (user_id,kind,text(180)), KEY (user_id,last_used)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS fin_memory (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, kind VARCHAR(12) NOT NULL DEFAULT 'line', text VARCHAR(300) NOT NULL, unit VARCHAR(30) NULL, unit_price DECIMAL(14,3) NULL, category VARCHAR(120) NULL, freq VARCHAR(60) NULL, item_kind VARCHAR(8) NULL, uses INT UNSIGNED NOT NULL DEFAULT 1, last_used DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY (user_id,kind,text(180)), KEY (user_id,last_used)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS rfq_settings (id TINYINT UNSIGNED PRIMARY KEY, enabled TINYINT(1) NOT NULL DEFAULT 1, mailbox_ids VARCHAR(200) NULL, assign_user_id INT UNSIGNED NULL, last_scan_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS rfqs (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(80) NOT NULL, code_source ENUM('email','generated','manual') NOT NULL DEFAULT 'email', client_name VARCHAR(190) NULL, client_email VARCHAR(190) NULL, subject VARCHAR(300) NULL, snippet TEXT NULL, received_at DATETIME NULL, due_date DATE NULL,
        status ENUM('new','quoting','quoted','revisited','on_hold','po_received','delivered','paid','lost','closed') NOT NULL DEFAULT 'new', msg_key CHAR(40) NULL, account_id INT UNSIGNED NULL, task_id INT UNSIGNED NULL, quote_doc_id INT UNSIGNED NULL, quote_number VARCHAR(40) NULL, quote_total DECIMAL(14,2) NULL, currency VARCHAR(8) NULL, quoted_at DATETIME NULL,
        po_number VARCHAR(80) NULL, po_received_at DATETIME NULL, po_from VARCHAR(190) NULL, po_subject VARCHAR(300) NULL, po_files VARCHAR(500) NULL, po_task_id INT UNSIGNED NULL, delivery_date DATE NULL, paid_at DATE NULL, paid_amount DECIMAL(14,2) NULL, pay_ref VARCHAR(120) NULL, notes TEXT NULL, created_by INT UNSIGNED NULL,
        created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY (code), KEY (status), KEY (client_email)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS rfq_events (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, rfq_id INT UNSIGNED NOT NULL, kind VARCHAR(16) NOT NULL, text VARCHAR(400) NOT NULL, user_id INT UNSIGNED NULL, at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY (rfq_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS rfq_msgs (msg_key CHAR(40) PRIMARY KEY, kind VARCHAR(12) NOT NULL DEFAULT 'seen', at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS delivery_notes (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, number VARCHAR(30) NOT NULL, rfq_id INT UNSIGNED NULL, quote_doc_id INT UNSIGNED NULL, client_name VARCHAR(190) NULL, client_address TEXT NULL, po_number VARCHAR(80) NULL, rfq_code VARCHAR(80) NULL, delivery_date DATE NULL, delivery_address VARCHAR(500) NULL, items MEDIUMTEXT NOT NULL, notes TEXT NULL,
        signed_by INT UNSIGNED NULL, signed_at DATETIME NULL, signature MEDIUMTEXT NULL, printed_at DATETIME NULL, printed_by INT UNSIGNED NULL, created_by INT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY (number), KEY (rfq_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    foreach ([['description', 'VARCHAR(500) NULL'], ['po_description', 'VARCHAR(500) NULL'], ['delivery_due', 'DATE NULL'], ['invoice_status', 'VARCHAR(30) NULL'], ['po_comments', 'TEXT NULL'], ['buyer_details', 'VARCHAR(500) NULL']] as [$c, $def]) if (!col_exists('rfqs', $c)) db()->exec("ALTER TABLE rfqs ADD COLUMN $c $def");
    $st = db()->query("SHOW COLUMNS FROM rfqs LIKE 'status'")->fetch(); if ($st && !str_contains((string)$st['Type'], 'revisited')) db()->exec("ALTER TABLE rfqs MODIFY status ENUM('new','quoting','quoted','revisited','on_hold','po_received','delivered','paid','lost','closed') NOT NULL DEFAULT 'new'");
    if (!col_exists('rfq_settings', 'allowed_senders')) db()->exec('ALTER TABLE rfq_settings ADD COLUMN allowed_senders TEXT NULL');
    foreach ([['items_json', 'MEDIUMTEXT NULL'], ['items_source', 'VARCHAR(190) NULL']] as [$c, $def]) if (!col_exists('rfqs', $c)) db()->exec("ALTER TABLE rfqs ADD COLUMN $c $def");
    db()->exec("CREATE TABLE IF NOT EXISTS rfq_files (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, rfq_id INT UNSIGNED NOT NULL, kind VARCHAR(6) NOT NULL DEFAULT 'rfq', name VARCHAR(190) NOT NULL, mime VARCHAR(100) NULL, size INT UNSIGNED NOT NULL DEFAULT 0, path VARCHAR(64) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY (rfq_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    foreach ([['website', 'VARCHAR(190) NULL'], ['category', 'VARCHAR(80) NULL'], ['dealing', "VARCHAR(10) NOT NULL DEFAULT 'not_yet'"], ['dealing_note', 'VARCHAR(300) NULL'], ['last_dealt_at', 'DATE NULL'], ['is_partner', 'TINYINT(1) NOT NULL DEFAULT 0'], ['partner_type', 'VARCHAR(60) NULL'], ['agreement_start', 'DATE NULL'], ['agreement_end', 'DATE NULL'], ['agreement_notes', 'TEXT NULL'], ['agreement_url', 'VARCHAR(500) NULL'], ['owner_id', 'INT UNSIGNED NULL'], ['source', 'VARCHAR(30) NULL'], ['updated_at', 'DATETIME NULL']] as [$c, $def]) if (!col_exists('vendors', $c)) db()->exec("ALTER TABLE vendors ADD COLUMN $c $def");
    if (!col_exists('contacts', 'vendor_id')) db()->exec('ALTER TABLE contacts ADD COLUMN vendor_id INT UNSIGNED NULL, ADD KEY (vendor_id)');
    if (!col_exists('vendors', 'is_regulator')) db()->exec('ALTER TABLE vendors ADD COLUMN is_regulator TINYINT(1) NOT NULL DEFAULT 0');
    if (!col_exists('contacts', 'contact_type')) db()->exec('ALTER TABLE contacts ADD COLUMN contact_type VARCHAR(20) NULL');
    foreach (['companies', 'contacts'] as $t) if (!col_exists($t, 'rfq_ok')) db()->exec("ALTER TABLE $t ADD COLUMN rfq_ok TINYINT(1) NOT NULL DEFAULT 0");
    if (!col_exists('pr_signals', 'scan_no')) db()->exec('ALTER TABLE pr_signals ADD COLUMN scan_no INT UNSIGNED NOT NULL DEFAULT 0, ADD KEY (scan_no)');
    if (!col_exists('pr_settings', 'scan_no')) db()->exec('ALTER TABLE pr_settings ADD COLUMN scan_no INT UNSIGNED NOT NULL DEFAULT 0');
    db()->exec("CREATE TABLE IF NOT EXISTS pr_stars (signal_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (signal_id,user_id), KEY (user_id), FOREIGN KEY (signal_id) REFERENCES pr_signals(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    if (!col_exists('weekly_reports', 'edit_open_until')) db()->exec('ALTER TABLE weekly_reports ADD COLUMN edit_open_until DATETIME NULL');
    db()->exec("CREATE TABLE IF NOT EXISTS weekly_edit_requests (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, weekly_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, reason VARCHAR(500) NULL, status ENUM('pending','approved','denied') NOT NULL DEFAULT 'pending', decided_by INT UNSIGNED NULL, decided_at DATETIME NULL, note VARCHAR(300) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY (weekly_id,status), FOREIGN KEY (weekly_id) REFERENCES weekly_reports(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    try { if (one("SHOW INDEX FROM pr_signals WHERE Key_name='uq_url'")) db()->exec('ALTER TABLE pr_signals DROP INDEX uq_url, ADD UNIQUE KEY uq_url_user (url_hash,user_id)'); } catch (Throwable $e) { error_log('Prospect index: ' . $e->getMessage()); }
    if (!col_exists('rfqs', 'payment_status')) db()->exec('ALTER TABLE rfqs ADD COLUMN payment_status VARCHAR(30) NULL');
    db()->exec("CREATE TABLE IF NOT EXISTS task_keeps (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, from_user INT UNSIGNED NULL, title VARCHAR(200) NOT NULL, snapshot MEDIUMTEXT NULL, state VARCHAR(10) NOT NULL DEFAULT 'new', new_task_id INT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY (user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    try {   // Insight: the engineer's real API (one GET with x-api-key) replaces the address and numbers we first assumed
        $ins = [['Users', 'number', 'sum', 'up', '', 'totalUsers'], ['Portfolios', 'number', 'sum', 'up', '', 'totalPortfolios'], ['Projects', 'number', 'sum', 'up', '', 'totalProjects'],
            ['Reports (all)', 'number', 'sum', 'up', 'reportsByOrg', 'total'], ['Reports generated', 'number', 'sum', 'up', 'reportsByOrg', 'generated'], ['Reports in draft', 'number', 'sum', 'up', 'reportsByOrg', 'draft'], ['Reports failed', 'number', 'sum', 'down', 'reportsByOrg', 'failed'],
            ['UT plans (all)', 'number', 'sum', 'up', 'utPlansByOrg', 'total'], ['UT plans generated', 'number', 'sum', 'up', 'utPlansByOrg', 'active'], ['UT plans in draft', 'number', 'sum', 'up', 'utPlansByOrg', 'draft'],
            ['Timelines (all)', 'number', 'sum', 'up', 'timelinesByOrg', 'total'], ['Timelines published', 'number', 'sum', 'up', 'timelinesByOrg', 'published'], ['Timelines in draft', 'number', 'sum', 'up', 'timelinesByOrg', 'draft'], ['Timelines archived', 'number', 'sum', 'up', 'timelinesByOrg', 'archived'],
            ['Storage used (MB)', 'number', 'sum', 'up', 'storageByOrg', 'total_mb'], ['Files stored', 'number', 'sum', 'up', 'storageByOrg', 'file_count']];
        foreach (all("SELECT id FROM exec_sources WHERE mode='pull' AND base_url LIKE '%insight.aerosub.co%'") as $src) {
            if (!one("SELECT id FROM exec_metrics WHERE source_id=? AND endpoint='/api/exec/analytics' LIMIT 1", [$src['id']])) continue;
            db()->prepare("DELETE FROM exec_metrics WHERE source_id=? AND endpoint='/api/exec/analytics'")->execute([$src['id']]); db()->prepare("UPDATE exec_sources SET auth_header='x-api-key', last_status=NULL WHERE id=?")->execute([$src['id']]);
            foreach ($ins as $i => [$label, $kind, $agg, $good, $list, $path]) { $mk = trim(substr(strtolower(preg_replace('/[^a-z0-9_]+/i', '_', $label)), 0, 60), '_');
                db()->prepare('INSERT IGNORE INTO exec_metrics (source_id,mkey,label,kind,endpoint,list_path,org_path,path,agg,good,position) VALUES (?,?,?,?,?,?,?,?,?,?,?)')->execute([$src['id'], $mk, $label, $kind, '/api/v1/integrations/analytics', $list ?: null, $list ? 'org_name' : null, $path, $agg, $good, $i]); }
            $log[] = 'Executive: Insight source moved to the real Analytics API (' . count($ins) . ' numbers)'; }
    } catch (Throwable $e) { error_log('Insight upgrade: ' . $e->getMessage()); }
    $log[] = 'Finance: product / service types, optional signatures and document comments ready.'; return $log;
}
if (!function_exists('migrate_finance3')) { function migrate_finance3(): array { return migrate_fin_ext(); } }   // (an older migrate_finance3 may already sit in migrate.php; migrate_fin_ext has its own name so it can never be shadowed)
